    using namespace std;

    class approximate_substring_set
    {
        /*!
            WHAT THIS OBJECT REPRESENTS
                This object is a tool for finding the substrings of a query string.  In
                particular, it stores a set of substrings and then you can ask it if a new
                string contains any of your substrings.  It will also tell you which
                substrings it finds.

                Importantly, this object gives only approximate answers because it uses a
                simple, but very fast hash table implementation which allows hash
                collisions.   In general, it will only accurately be able to store about
                8000 substrings in its substring search set.  Adding more than this by
                calling add_substring() will begin overwriting previous substrings.
        !*/

    public:

        approximate_substring_set(
        ) :
            mask(0x1FFF),
            mask_bits(13), // how many bits are set to 1 in mask
            init_hash(0xFFFFFFFF),
            max_substr_len(0)
        {
            fill_crc_table();
            hash_table.resize(mask+1);
        }

        dlib::uint16 max_substring_id (
        ) const { return hash_table.size()-1; }
        /*!
            ensures
                - Returns the max possible value that a substring ID can take.  These are
                  the values returned by add_substring() and placed into the hits vectors
                  by find_substrings().
        !*/

        dlib::uint16 add_substring (
            const std::string& str
        )
        /*!
            ensures
                - Inserts the given string into this object.  This means that subsequent
                  calls to find_substrings() will search the given string to see if str is
                  one of its substrings.
                - The substring ID value given to str is returned.  This is the value which
                  will appear in the hits vector output by find_substrings() when str is
                  found in a string.  It is also always <= max_substring_id().
                - This object stores the substring database in an approximate hash table
                  structure.  This means that calls to add_substring() have a small chance
                  of removing substrings previously added by add_substring().  So when
                  populating this object with substrings you should give the most important
                  substrings you wish to find last. 
                - You can use the '*' character to denote the beginning or end of a string.
                  So for example, if you want your substring to match only words ending in
                  "ed" then you can set str to "ed*"
        !*/
        {
            dlib::uint32 h = init_hash;
            for (unsigned long i = 0; i < str.size(); ++i)
                add_to_hash(h, str[i]);

            if (str.size() > max_substr_len)
                max_substr_len = str.size();

            const dlib::uint16 str_id = static_cast<dlib::uint16>(h>>mask_bits);
            const dlib::uint16 bucket_id = static_cast<dlib::uint16>(h&mask);
            hash_table[bucket_id] = str_id;
            return bucket_id;
        }

        void find_substrings (
            const char* begin,
            const char* end,
            std::vector<dlib::uint16>& hits
        ) const
        /*!
            requires
                - begin <= end
            ensures
                - #hits.size() == The number of substrings of the string contained in the
                  half open range [begin, end) which match one of the strings given to this
                  object's add_substring() method.
                - #hits == The set of substring ID values which were found in the input string.
                - All elements of #hits are <= max_substring_id()
        !*/
        {
            const int max_len = 50;
            dlib::uint32 hashes[max_len];
            // We are only going to look at the first max_len-1 characters in the string.
            // If it's longer than that then too bad, it won't be part of the hash.
            end = std::min(end, begin + max_len-1);
            hits.clear();

            if (begin == end)
                return;

            // initialize hashes
            dlib::uint32* ptr = hashes;
            *ptr++ = init_hash;
            for (const char* i = begin; i < end; ++i)
                *ptr++ = init_hash;
            // The first hash bucket is at the front of the string so indicate that it
            // starts with the special '*' string ending marker.
            add_to_hash(hashes[0], '*');


            for (unsigned int iter = 0; iter < max_substr_len && begin<end; ++iter)
            {
                ptr = hashes;
                add_to_hash(*ptr, *begin);
                add_hash_if_in_table(*ptr++, hits);
                for (const char* i = begin; i < end; ++i)
                {
                    add_to_hash(*ptr, *i);
                    add_hash_if_in_table(*ptr++, hits);
                }
                ++begin;

                dlib::uint32 end_hash = *(ptr-1);
                add_to_hash(end_hash, '*');
                add_hash_if_in_table(end_hash, hits);
            }
        }

        void find_substrings (
            const std::string& str,
            std::vector<dlib::uint16>& hits
        ) const
        /*!
            ensures
                - This function is identical to the above find_substrings() routine except
                  that it takes its input string as a std::string instead of an iterator
                  range.
        !*/
        {
            if (str.size() != 0)
            {
                find_substrings(&str[0], &str[0] + str.size(), hits);
            }
            else
            {
                hits.clear();
            }
        }

        friend void serialize(const approximate_substring_set& item, std::ostream& out)
        {
            int version = 1;
            dlib::serialize(version, out); 
            dlib::serialize(item.mask, out); 
            dlib::serialize(item.mask_bits, out); 
            dlib::serialize(item.init_hash, out); 
            dlib::serialize(item.max_substr_len, out); 
            dlib::serialize(item.hash_table, out); 
            dlib::serialize(item.crc_table, out); 
        }

        friend void deserialize(approximate_substring_set& item, std::istream& in)
        {
            int version = 0;
            dlib::deserialize(version, in); 
            if (version != 1)
                throw dlib::serialization_error("Unexpected version found while deserializing mitie::approximate_substring_set");
            dlib::deserialize(const_cast<dlib::uint32&>(item.mask), in); 
            dlib::deserialize(const_cast<dlib::uint32&>(item.mask_bits), in); 
            dlib::deserialize(const_cast<dlib::uint32&>(item.init_hash), in); 
            dlib::deserialize(item.max_substr_len, in); 
            dlib::deserialize(item.hash_table, in); 
            dlib::deserialize(item.crc_table, in); 
        }

    // ------------------------------------------------------------------------------------
    // ------------------------------------------------------------------------------------
    //                                  IMPLEMENTATION DETAILS
    // ------------------------------------------------------------------------------------
    // ------------------------------------------------------------------------------------

    private:

        /*!
            We are going to use a crc32 hash for hashing substrings.  The crc_table object stores
            some numbers needed as part of crc32 hash calculation and the hash_table vector is what
            records what substrings are in our object at any given moment.
        !*/

        const dlib::uint32 mask;
        const dlib::uint32 mask_bits;
        const dlib::uint32 init_hash;
        unsigned int max_substr_len;
        std::vector<dlib::uint16> hash_table;
        std::vector<dlib::uint32> crc_table;

        inline void add_hash_if_in_table (
            const dlib::uint32 hash,
            std::vector<dlib::uint16>& hits
        ) const
        {
            const dlib::uint16 str_id = static_cast<dlib::uint16>(hash>>mask_bits);
            const dlib::uint16 bucket_id = static_cast<dlib::uint16>(hash&mask);
            if (hash_table[bucket_id] == str_id)
                hits.push_back(bucket_id);
        }

        inline void add_to_hash (
            dlib::uint32& hash,
            unsigned char item
        ) const
        /*!
            ensures
                - incorporates item into the hash value in hash.
        !*/
        {
            hash = (hash>>8) ^ crc_table[(hash^item) & 0xFF];
        }

        void fill_crc_table (
        )
        {
            dlib::uint32 temp;

            crc_table.resize(256);
            // fill out crc_table
            for (dlib::uint32 i = 0; i < 256; ++i)
            {
                temp = i;
                for (dlib::uint32 j = 0; j < 8; ++j)
                {
                    if (temp&1)
                        temp = (temp>>1)^0xedb88320;
                    else
                        temp >>= 1;
                }
                crc_table[i] = temp;
            }
        }
    };
}

namespace mitie
{
    class word_morphology_feature_extractor
    {
    public:
        word_morphology_feature_extractor(){}

        word_morphology_feature_extractor (
            const approximate_substring_set& substrings_,
            const dlib::matrix<float>& morph_trans_
        ) :
            substrings(substrings_),
            morph_trans(morph_trans_) 
        {}

        unsigned long get_num_dimensions(
        ) const
        {
            return morph_trans.nc();
        }

        void get_feature_vector (
            const char* begin,
            const char* end,
            dlib::matrix<float,0,1>& feats
        ) const
        {
            substrings.find_substrings(begin, end, hits);
            hits_to_vect(hits, feats);
        }

        void premultiply_vectors_by (
            double value
        )
        {
            morph_trans *= value;
        }

        void get_feature_vector (
            const std::string& word,
            dlib::matrix<float,0,1>& feats
        ) const
        {
            substrings.find_substrings(word, hits);
            hits_to_vect(hits, feats);
        }

        friend void serialize (const word_morphology_feature_extractor& item, std::ostream& out)
        {
            int version = 1;
            dlib::serialize(version, out);
            serialize(item.substrings, out);
            dlib::serialize(item.morph_trans, out);
        }

        friend void deserialize (word_morphology_feature_extractor& item, std::istream& in)
        {
            int version = 0;
            dlib::deserialize(version, in);
            if (version != 1)
                throw dlib::serialization_error("Unexpected version found while deserializing mitie::word_morphology_feature_extractor");
            deserialize(item.substrings, in);
            dlib::deserialize(item.morph_trans, in);
        }

    private:

        void hits_to_vect (
            const std::vector<dlib::uint16>& hits,
            dlib::matrix<float,0,1>& feats
        ) const
        {
            if (hits.size() == 0)
            {
                feats.set_size(morph_trans.nc());
                feats = 0;
            }
            else
            {
                feats = trans(rowm(morph_trans,hits[0]));
                for (unsigned long i = 1; i < hits.size(); ++i)
                    feats += trans(rowm(morph_trans,hits[i]));
            }
        }

        approximate_substring_set substrings;
        dlib::matrix<float> morph_trans;
        mutable std::vector<dlib::uint16> hits;
    };
}

namespace mitie 
{

    class total_word_feature_extractor
    {
        /*!
            WHAT THIS OBJECT REPRESENTS
                This is a tool for turning a word into a short and dense vector which
                describes what kind of places in text a word can appear.  This is done
                using both word morphology and general distributional word features.  Or in
                other words, this object is basically a combination of the
                word_morphology_feature_extractor along with a general table mapping words
                to descriptive feature vectors (generally created from some CCA based
                distributional feature thing).

            THREAD SAFETY
                Note that this object uses mutable internal scratch space.  Therefore, it is
                unsafe for two threads to touch the same instance of this object at a time
                without mutex locking it first.
        !*/

        inline static std::string convert_numbers (
            const std::string& str_
        )
        {
            std::string str(str_);
            for (unsigned long i = 0; i < str.size(); ++i)
            {
                if ('0' <= str[i] && str[i] <= '9')
                    str[i] = '#';
            }
            return str;
        }

    public:

        total_word_feature_extractor() : fingerprint(0), non_morph_feats(0) {}

        total_word_feature_extractor(
            const std::map<std::string, dlib::matrix<float,0,1> >& word_vectors,
            const word_morphology_feature_extractor& morph_fe_
        ) :
            morph_fe(morph_fe_)
        {
            DLIB_CASSERT(word_vectors.size() != 0, "Invalid arguments");

            std::map<std::string, dlib::matrix<float,0,1> >::const_iterator i;

            i = word_vectors.begin();
            non_morph_feats = i->second.size() + 1; // plus one for the OOV indicator


            // now figure out how to relatively scale the word_vectors and morph features.
            dlib::running_stats<double> rs_word, rs_morph;
            dlib::matrix<float,0,1> feats;
            for (; i != word_vectors.end(); ++i)
            {
                morph_fe.get_feature_vector(i->first, feats);
                rs_morph.add(mean(abs(feats)));
                rs_word.add(mean(abs(i->second)));
            }

            // scale the morphological features so they have an average feature value of 1.
            morph_fe.premultiply_vectors_by(1/rs_morph.mean());

            // We also want to scale the word vectors to have an average feature value of 1.
            const double scale = 1/rs_word.mean();
            // Now go though all the words again and compute the complete feature vectors for
            // each and store that into total_word_vectors.
            for (i = word_vectors.begin(); i != word_vectors.end(); ++i)
            {
                morph_fe.get_feature_vector(i->first, feats);
                total_word_vectors[i->first] = join_cols(join_cols(dlib::zeros_matrix<float>(1,1), scale*i->second), feats);
            }


            // finally, don't forget to set the fingerprint to something
            compute_fingerprint();
        }

        dlib::uint64 get_fingerprint(
        ) const { return fingerprint; }
        /*!
            ensures
                - returns a 64bit ID number that uniquely identifies this object instance.
                  The ID is computed based on the state of this object, so any copy of it
                  that has the same state will have the same fingerprint ID number.  This
                  is useful since down stream models that have been trained to use a
                  specific total_word_feature_extractor instance can record the fingerprint
                  of the total_word_feature_extractor they used and use that fingerprint ID
                  to verify that the same total_word_feature_extractor is being used later
                  on.
        !*/

        void get_feature_vector(
            const std::string& word_,
            dlib::matrix<float,0,1>& feats
        ) const
        /*!
            ensures
                - #feats == a dense vector describing the given word
                - #feats.size() == get_num_dimensions()
        !*/
        {
            const std::string word = convert_numbers(word_);
            std::map<std::string, dlib::matrix<float,0,1> >::const_iterator i;
            i = total_word_vectors.find(word);
            if (i != total_word_vectors.end())
            {
                feats = i->second;
                return;
            }

            if (get_num_dimensions() == 0)
            {
                feats.set_size(0);
                return;
            }

            morph_fe.get_feature_vector(word, temp);
            feats = join_cols(dlib::zeros_matrix<float>(non_morph_feats,1), temp);
            // This is an indicator feature used to model the fact that this word is
            // outside our dictionary.
            feats(0) = 1;
        }

        unsigned long get_num_dimensions(
        ) const
        /*!
            ensures
                - returns the dimensionality of the feature vectors produced by this
                  object.
        !*/
        {
            return non_morph_feats + morph_fe.get_num_dimensions();
        }

        unsigned long get_num_words_in_dictionary (
        ) const
        {
            return total_word_vectors.size();
        }

        std::vector<std::string> get_words_in_dictionary (
        ) const
        {
            std::vector<std::string> temp;
            temp.reserve(total_word_vectors.size());
            std::map<std::string, dlib::matrix<float,0,1> >::const_iterator i;
            for (i = total_word_vectors.begin(); i != total_word_vectors.end(); ++i)
            {
                temp.push_back(i->first);
            }
            return temp;
        }

        friend void serialize(const total_word_feature_extractor& item, std::ostream& out)
        {
            int version = 2;
            dlib::serialize(version, out);
            dlib::serialize(item.fingerprint, out);
            dlib::serialize(item.non_morph_feats, out);
            dlib::serialize(item.total_word_vectors, out);
            serialize(item.morph_fe, out);
        }

        friend void deserialize(total_word_feature_extractor& item, std::istream& in)
        {
            int version = 0;
            dlib::deserialize(version, in);
            if (version != 2)
                throw dlib::serialization_error("Unexpected version found while deserializing total_word_feature_extractor.");
            dlib::deserialize(item.fingerprint, in);
            dlib::deserialize(item.non_morph_feats, in);
            dlib::deserialize(item.total_word_vectors, in);
            deserialize(item.morph_fe, in);
        }

    private:

        void compute_fingerprint()
        {
            std::vector<char> buf;
            dlib::vectorstream sout(buf);
            sout << "fingerprint";
            dlib::serialize(non_morph_feats, sout);
            dlib::serialize(total_word_vectors, sout);
            serialize(morph_fe, sout);

            fingerprint = dlib::murmur_hash3_128bit(&buf[0], buf.size()).first;
        }

        dlib::uint64 fingerprint;
        long non_morph_feats;
        std::map<std::string, dlib::matrix<float,0,1> > total_word_vectors;
        word_morphology_feature_extractor morph_fe;

        // This object does not logically contribute to the state of this object.  It is
        // just here to avoid reallocating it over and over in get_feature_vector().
        mutable dlib::matrix<float,0,1> temp;
    };

}

class ner_feature_extractor
    {

    public:
        typedef std::vector<dlib::matrix<float,0,1> > sequence_type;

        ner_feature_extractor() :num_feats(1) {}

        ner_feature_extractor (
            unsigned long num_feats_
        ) :
            num_feats(num_feats_)
        {}

        unsigned long num_feats;

        const static bool use_BIO_model           = false;
        const static bool use_high_order_features = false;
        const static bool allow_negative_weights  = true;

        unsigned long window_size()  const { return 3; }

        unsigned long num_features() const { return num_feats; }

        template <typename feature_setter>
        void get_features (
            feature_setter& set_feature,
            const sequence_type& sentence,
            unsigned long position
        ) const
        {
            const dlib::matrix<float,0,1>& feats = sentence[position];
            for (long i = 0; i < feats.size(); ++i)
                set_feature(i, feats(i));
