import random
import string
from typing import List

# Target data type: UTF-8 text used by tokenizers and other text-processing APIs.
# We generate varied but valid UTF-8 strings that can exercise:
# - Whitespace/token boundaries (spaces, tabs, newlines, non-breaking spaces)
# - Punctuation splitting rules (.,!?()[],:| quotes, apostrophes)
# - Digits (0-9) to hit number-normalization paths
# - ASCII and a selection of multi-byte UTF-8 characters (curly quotes, NBSP, ellipsis, em dash)
# - Mixed-case words and abbreviations (Jr., St.) to trigger tokenizer special cases
# - Repeated and long tokens, but cap total size <= 4096 bytes as required
# - Gigaword-like XML snippets for the Gigaword readers/parsers
#
# The generator returns bytes representing a UTF-8 encoded string; callers pass it
# to FUZZ_PARAM_STR or write to FUZZ_PARAM_FILENAME as needed.

ASCII_WORDS = [
    "Hello", "world", "MITIE", "tokenizer", "NER", "relation", "detector",
    "feature", "vector", "sample", "text", "categorizer", "trainer",
    "BIO", "BILOU", "entity", "chunk", "offset", "Unicode", "UTF8",
    "example", "testing", "increment", "hash", "matrix", "serialize",
    "deserialize", "CoNLL", "Gigaword", "dataset", "model", "score",
    "precision", "recall", "location", "organization", "person",
]

# Common punctuation and separators used by conll_tokenizer rules
PUNCT = list("[]().!,\":|?;:/-_")

# UTF-8 multi-byte characters of interest
UNICODE_SNIPPETS = [
    "\u00A0",      # non-breaking space (NBSP)
    "\u2019",      # right single quotation mark (’)
    "\u201C",      # left double quotation mark (“)
    "\u201D",      # right double quotation mark (”)
    "\u2026",      # ellipsis (…) 
    "\u2014",      # em dash (—)
    "\u00E9",      # é
    "\u010D",      # č
    "\u4F60\u597D",  # 你好
    "\u041F\u0440\u0438\u0432\u0435\u0442",  # Привет
]

DIGITS = list(string.digits)
WS = [" ", "\t", "\n", "\r", "\u00A0"]

ABBREV = ["Mr.", "Mrs.", "Dr.", "Jr.", "St.", "Inc.", "Ltd.", "Co."]

QUOTES_CASES = [
    "\u201Cquote\u201D",        # “quote”
    "\u2018quote\u2019",        # ‘quote’
    "\u201Chello\u2019s\u201D",  # “hello’s” with curly apostrophe inside
    "\"quoted\"",            # ASCII quotes
]

# Small XML-ish blocks for gigaword parser
def make_gigaword_doc(rnd: random.Random) -> str:
    def pick_word(max_len=10):
        w = rnd.choice(ASCII_WORDS)
        if rnd.random() < 0.5:
            w = w.lower()
        return w[:max_len]
    id_part = pick_word(12)
    headline = " ".join(pick_word(8) for _ in range(rnd.randint(2,5)))
    dateline = " ".join(pick_word(8) for _ in range(rnd.randint(2,4)))
    text = " ".join(pick_word(10) for _ in range(rnd.randint(5,20)))
    return f"<DOC id=\"{id_part}\" type=\"story\"><HEADLINE>{headline}</HEADLINE><DATELINE>{dateline}</DATELINE><TEXT>{text}</TEXT></DOC>"

def make_number_token(rnd: random.Random) -> str:
    # Mix digits with separators to trigger tokenizer numeric handling
    parts = []
    n = rnd.randint(1, 4)
    for i in range(n):
        chunk = "".join(rnd.choice(DIGITS) for _ in range(rnd.randint(1,4)))
        parts.append(chunk)
        if i != n-1:
            parts.append(rnd.choice([",", "."]))
    return "".join(parts)

def make_token(rnd: random.Random) -> str:
    choice = rnd.random()
    if choice < 0.25:
        return rnd.choice(ASCII_WORDS)
    elif choice < 0.40:
        return rnd.choice(UNICODE_SNIPPETS)
    elif choice < 0.55:
        return make_number_token(rnd)
    elif choice < 0.70:
        return rnd.choice(ABBREV)
    elif choice < 0.82:
        base = rnd.choice(ASCII_WORDS)
        # sprinkle punctuation
        return base + rnd.choice(PUNCT)
    elif choice < 0.94:
        return rnd.choice(QUOTES_CASES)
    else:
        # random alnum token length 1..12
        L = rnd.randint(1,12)
        alphabet = string.ascii_letters + string.digits
        s = "".join(rnd.choice(alphabet) for _ in range(L))
        return s

def make_sentence(rnd: random.Random, max_tokens: int) -> str:
    # Build a sentence mixing tokens and whitespace, plus some punctuation
    tokens: List[str] = []
    n = rnd.randint(max(1, max_tokens//3), max_tokens)
    for _ in range(n):
        t = make_token(rnd)
        # sometimes wrap with punctuation that splits in CoNLL tokenizer
        if rnd.random() < 0.15:
            t = rnd.choice(["(", "["]) + t + rnd.choice([")", "]"])
        tokens.append(t)
    # join with mixed whitespace
    out = []
    for i, t in enumerate(tokens):
        out.append(t)
        if i != len(tokens)-1:
            # delimiter
            if rnd.random() < 0.7:
                out.append(rnd.choice(WS))
            else:
                out.append(" ")
    # sometimes add sentence-final punctuation
    if rnd.random() < 0.6:
        out.append(rnd.choice([".", "!", "?", "...", "\u2026"]))
    return "".join(out)

def make_paragraph(rnd: random.Random, max_tokens: int) -> str:
    # Build 1-5 sentences separated by newlines
    k = rnd.randint(1, 5)
    per = max(1, max_tokens // k)
    sents = [make_sentence(rnd, per) for _ in range(k)]
    return "\n".join(sents)

def assemble_corpus(rnd: random.Random) -> str:
    parts: List[str] = []
    # Mix of paragraphs, a gigaword doc, and lines with special tokens
    if rnd.random() < 0.8:
        parts.append(make_paragraph(rnd, rnd.randint(20, 120)))
    if rnd.random() < 0.6:
        parts.append(make_gigaword_doc(rnd))
    # Add lines with many numbers and abbreviations
    line = []
    for _ in range(rnd.randint(5, 15)):
        line.append(make_number_token(rnd))
        line.append(rnd.choice([", ", " "]))
        line.append(rnd.choice(ABBREV))
        line.append(rnd.choice([" ", "\n"]))
    parts.append("".join(line))
    # Add a quote-heavy line
    parts.append(" ".join(rnd.choice(QUOTES_CASES) for _ in range(rnd.randint(3,8))))
    # Optionally a long word list to drive dictionary/OOV paths
    if rnd.random() < 0.5:
        parts.append(" ".join(rnd.choice(ASCII_WORDS) for _ in range(rnd.randint(10,40))))
    text = "\n".join(parts)
    # Ensure not exceeding 4096 bytes; trim at boundary without breaking UTF-8 (simple safe trim)
    b = text.encode('utf-8')
    if len(b) <= 4096:
        return text
    # trim preserving UTF-8 by backing off to a valid boundary
    b = b[:4096]
    # Try decoding; if fails, back off a few bytes
    for back in range(0, 4):
        try:
            return b[:4096-back].decode('utf-8', errors='strict')
        except UnicodeDecodeError:
            continue
    # Fallback permissive decode
    return b.decode('utf-8', errors='ignore')


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    text = assemble_corpus(rnd)
    return text.encode('utf-8')

import os
import random
import string
from typing import List

# Data type: filesystem path
# Target stubs expect FUZZ_PARAM_FILENAME to yield a path where the program may read/write.
# We generate a variety of plausible file paths, including:
# - Simple filenames
# - Nested directories (not created; fuzzer harness may manage I/O)
# - Paths with extensions used by MITIE (.dat, .model, .ner, .tcat, .bin)
# - Paths with unusual but valid characters, spaces, unicode, and long names
# - Absolute and relative paths
# - Hidden files (leading dot)
# The buffer is a single path string, null-terminated is not required; FUZZ runtime reads bytes.

EXTS = [
    "dat", "model", "ner", "tcat", "bin", "fe", "pure", "txt",
]

UNICODE_FRAGMENTS = [
    "naïve", "résumé", "数据", "данные", "παράδειγμα", "例", "😀", "ö", "ß",
]

SAFE_PUNCT = "-_.,+#@!%()[]{}="

def _rand_name(rng: random.Random, min_len: int = 3, max_len: int = 16) -> str:
    n = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + SAFE_PUNCT
    return ''.join(rng.choice(alphabet) for _ in range(n)).strip()

def _rand_unicode_component(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(UNICODE_FRAGMENTS)
    # mix ascii and a unicode fragment
    return _rand_name(rng, 2, 6) + rng.choice(UNICODE_FRAGMENTS) + _rand_name(rng, 1, 4)

def _with_extension(rng: random.Random, base: str) -> str:
    if rng.random() < 0.85:
        ext = rng.choice(EXTS)
        return f"{base}.{ext}"
    return base

def _random_dirs(rng: random.Random) -> List[str]:
    depth = rng.choices([0,1,2,3,4], weights=[4,4,3,2,1])[0]
    parts = []
    for i in range(depth):
        if rng.random() < 0.3:
            part = _rand_unicode_component(rng)
        else:
            part = _rand_name(rng, 1, 12)
        # occasionally hidden dir
        if rng.random() < 0.15:
            part = "." + part.lstrip('.')
        parts.append(part)
    return parts

def _absolute_prefix(rng: random.Random) -> str:
    # Produce platform-agnostic absolute-like prefixes; harness may run on POSIX.
    # We focus on POSIX style but include a chance for Windows-like to test path handling.
    choice = rng.random()
    if choice < 0.8:
        return "/"
    elif choice < 0.9:
        # temp-like base
        return "/tmp/"
    else:
        # Windows-like
        drive = rng.choice(string.ascii_uppercase)
        return f"{drive}:/"

def _relative_prefix(rng: random.Random) -> str:
    options = ["", "./", "../", "../../", "./.hidden/", "./build/"]
    return rng.choice(options)

def _compose_path(rng: random.Random) -> str:
    # Decide absolute vs relative
    if rng.random() < 0.6:
        prefix = _relative_prefix(rng)
    else:
        prefix = _absolute_prefix(rng)

    parts = _random_dirs(rng)

    # filename
    if rng.random() < 0.25:
        base = _rand_unicode_component(rng)
    else:
        base = _rand_name(rng, 3, 24)

    # occasionally hidden file
    if rng.random() < 0.15 and (not base.startswith('.')):
        base = "." + base

    fname = _with_extension(rng, base)

    # Join with POSIX separators; Windows-like prefixes still acceptable to most harnesses
    path = prefix + "/".join([p for p in parts if p])
    if path and not path.endswith("/"):
        path += "/"
    path += fname

    # Occasionally append trailing spaces or safe punctuation that filesystems accept
    if rng.random() < 0.1:
        path += rng.choice(["", " ", " (1)", "~"])

    # Limit to 255 per component typical; ensure overall length <= 4096
    if len(path) > 4096:
        path = path[:4096]
    return path

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Generate multiple candidate paths and pick one with diversity heuristic
    candidates = [_compose_path(rng) for _ in range(rng.randint(1, 3))]

    # Prefer paths under tmp-like to increase writability chances for save stubs
    def score(p: str) -> int:
        s = 0
        if p.startswith("/tmp/") or p.startswith("./") or p.startswith("../"):
            s += 2
        if any(p.endswith("." + ext) for ext in EXTS):
            s += 1
        if "/" in p:
            s += 1
        return s

    best = max(candidates, key=score)

    # Return as utf-8 bytes; no trailing NUL needed
    data = best.encode('utf-8', errors='ignore')
    # Ensure non-empty
    if not data:
        data = b"/tmp/mitie_model.dat"
    return data
